from pathlib import Path
import json,html,wave
R=Path(__file__).resolve().parent.parent
pages=json.loads((R/'manifest.json').read_text());refs=json.loads((R/'references/sources.json').read_text())
def e(s):return html.escape(str(s),quote=True)
def figure(src,title,caption='',cls=''):
 return f'<figure class="{cls}"><a href="{e(src)}"><img loading="lazy" src="{e(src)}" alt="{e(title)}"></a><figcaption><b>{e(title)}</b> {e(caption)}</figcaption></figure>'
sections=[]
sections.append('''<header><p class="eyebrow">TRAIL WARS / ART DIRECTION REVIEW / 10 NOV 2026</p><h1>Small racers.<br><em>Big personality.</em></h1><p class="lead">Three original directions. One honest playfield.<br>Research → compare → design → your approval.</p><p class="notice">All proposed screens are editable design mockups, <b>not Roblox captures or implemented UI</b>. No gameplay, renderer, persistence or sound uploads were changed in this phase.</p><nav><a href="#current">Current</a><a href="#references">Research</a><a href="#concepts">3 concepts</a><a href="#proposed">Recommended</a><a href="#motion">Motion</a><a href="#decision">Decision</a></nav></header>''')
sections.append('<section id="current"><p class="eyebrow">01 / EXISTING GAME — ACTUAL STUDIO CAPTURES</p><h2>A foundation worth preserving.<br>A hierarchy worth improving.</h2><p>Starting HEAD verified as b1767db. Pending Candy Comet work and QA were preserved as 7419afd on the playable visual branch before this separate design branch. bbd39c7 remains the known-working fallback.</p><div class="grid two">')
for file,t,d in [('after-home.png','Current Home','Repeated bordered navigation; cartoon faces are present.'),('actual-gameplay.png','Current gameplay','Actual pre-detail-threshold capture; small racers and equally weighted boxes.'),('after-results.png','Current Results','Actual winner strip and repeated standings rows.'),('../candy-comet/after-portrait.png','Earlier approved slice / portrait','Actual Studio replay, not a physical phone or real human match.')]:
 src='../../qa/candy-finalization/'+file if not file.startswith('../') else '../../qa/candy-comet/after-portrait.png'
 sections.append(figure(src,t,d,'portrait' if 'portrait' in file else ''))
sections.append('</div><p><a href="current-ui-audit.md">Read the evidence-based audit</a> · <a href="../../qa/playtest-2026-11-10/verified-normal-gameplay.mp4">Baseline actual Studio recording</a> · <a href="../../qa/candy-finalization/final-source-gameplay.mp4">Recent actual Studio recording</a></p><p class="notice">Carry-forward risk: latest two-client test failed client Final/winner presentation assertions. This checkpoint is not certified ready. Managed-client render stalls remain unresolved; no engine cause or physical-device FPS is claimed.</p></section>')
sections.append('<section id="references"><p class="eyebrow">02 / REAL REFERENCE EVIDENCE</p><h2>Eight games. Different lessons.</h2><p>Saved screenshots were visually inspected. Historical dates are explicit. We do not endorse every interface or claim to have viewed moving footage/audio when only a source link was available. Reference images belong to their respective creators and are not Trail Wars assets.</p><div class="grid three">')
for r in refs:
 if 'file' not in r:continue
 src='references/'+r['file'];sections.append('<article>'+figure(src,r['game']+' / '+r['kind'],r['sourceDate'])+f'<p><a href="{e(r["page"])}">Image source</a> · <a href="{e(r["official"])}">Official game</a></p>'+ (f'<p><a href="{e(r["video"])}">Linked footage / index</a> <small>Moving playback not inspected.</small></p>' if r['video'] else '<p><small>No direct video verified for this record.</small></p>')+'</article>')
sections.append('</div><p><a href="reference-research.md">Analysis of palette, type, construction, character integration, HUD, strengths, weaknesses and evidence gaps</a> · <a href="references/sources.json">Attribution and download manifest</a></p><h3>What transfers</h3><div class="grid three"><p><b>Character-first composition.</b> PHIGHTING and Dandy show why expression should carry the screen, while supporting chrome gets quieter.</p><p><b>One visual substrate.</b> Block Tales supports a consistent paper hypothesis. A sticker shape must agree with its lettering, outline and icon art.</p><p><b>Selective, not universal.</b> Tower Heroes inspection is useful; Bee Swarm/Epic inventory density is a counterexample for active steering.</p></div><p>Beyond Roblox: <a href="https://www.nintendo.com/us/store/products/snipperclips-cut-it-out-together-switch/">Snipperclips official gallery</a> for shape-as-character; <a href="https://www.nintendo.com/us/store/products/super-mario-party-jamboree-switch/">Mario Party Jamboree official gallery</a> for physical placement. These motivate original directions, not copied assets or measured animation timings.</p></section>')
sections.append('<section id="concepts"><p class="eyebrow">03 / ORIGINAL ALTERNATIVES — UNIMPLEMENTED</p><h2>Three construction systems.<br>Not three recolors.</h2><div class="grid three">')
for k,name,desc in [('a','Candy Comet Arcade','Finned comets, selective toy depth, open Home and quiet match framing.'),('b','Stickerbook Showdown','Cut edges, Kalam lettering, race-notes HUD and a round-by-round scrapbook.'),('c','Miniature Toy Arena','Molded capsules, ability paddles, score tokens and podium results.')]:
 sections.append(f'<article><h3>{k.upper()} / {name}</h3><p>{desc}</p>')
 for label in ['moodboard','home-desktop','hud-desktop','results-desktop','hud-portrait']:
  id=(k+'-moodboard') if label=='moodboard' else 'concept-'+k+'-'+label
  sections.append(figure('exports/'+id+'.png',label,'Original design proposal', 'portrait' if 'portrait' in label else ''))
 sections.append('</article>')
sections.append('</div><p><a href="concept-comparison.md">Weighted comparison and candid trade-offs</a> · <a href="exports/concept-comparison.png">Open 3 × 3 comparison sheet</a></p><p class="notice"><b>Recommendation: A, subject to your approval.</b> Strongest continuity with SNAP ARCADE and existing native foundations. B is the strongest handmade alternative. C has the best tabletop ceremony but the largest mobile/layering risk. No option receives a free pass on competitive readability.</p></section>')
sections.append('<section id="proposed"><p class="eyebrow">04 / REFINED PROPOSAL A — SAMPLE DATA</p><h2>Candy Comet, with intent.</h2><p>A large character where it helps. Small truthful racers where it matters. The active arena stays 1300:800; its geometry is not enlarged to flatter the design. Home does not scroll.</p>'+figure('exports/a-home-desktop.png','Proposed Home / desktop 1280 × 720','Original editable design; not a Roblox screenshot.')+'<div class="controls"><button data-filter="all">All sizes</button><button data-filter="desktop">Desktop</button><button data-filter="portrait">Portrait</button><button data-filter="landscape">Compact landscape</button></div><div class="grid three" id="screens">')
for p in pages:
 if not p['file'].startswith('screen-designs/'):continue
 device='landscape' if 'landscape' in p['id'] else 'portrait' if 'portrait' in p['id'] else 'tablet' if 'tablet' in p['id'] else 'desktop'
 sections.append(f'<div data-device="{device}">'+figure('exports/'+p['id']+'.png',p['label'],f'{p["width"]} × {p["height"]} usable composition', 'portrait' if device in ['portrait','tablet'] else '')+f'<p><a href="{p["file"]}">Editable SVG</a></p></div>')
sections.append('</div><p>Profile numbers are illustrative, not live account data. Shop/Customize use the four actual catalog entries; inspection, ownership and equip states remain distinct. No live purchase is represented as working.</p></section>')
sections.append('<section id="parts"><p class="eyebrow">05 / PARTS AND STATES</p><h2>Depth belongs to actions.</h2>')
for id in ['a-component-system','navigation-icons','a-important-states']:sections.append(figure('exports/'+id+'.png',id,'Original separate components; native labels and controls would remain interactive.'))
sections.append('<p><a href="component-designs/hover-racer.svg">Racer source</a> · <a href="component-designs/homing-rocket.svg">Homing source</a> · <a href="component-designs/turret-rocket.svg">Turret source</a> · <a href="component-designs/action-face-9slice.svg">9-slice action skin</a> · <a href="style-guide.md">Style guide / asset plan</a></p></section>')
sections.append('<section id="motion"><p class="eyebrow">06 / MOTION AND SOUND — LOCAL DESIGN PREVIEW</p><h2>Anticipation. Action. Consequence. Rest.</h2><iframe title="Interactive proposed score motion" src="motion-storyboards/interactive-preview.html" loading="lazy"></iframe>'+figure('exports/a-motion-storyboard.png','Motion sequence','Original timing hypotheses, not measured Nintendo animation.')+'<p><a href="motion-storyboards/interaction-spec.md">Complete event, cancellation, reduced-motion and audio storyboard</a></p><h3>Existing original sound candidates</h3><p>Prepared local WAVs only. Optional manual playback below. Current Roblox fallback is silent; no assets were uploaded or enabled during this phase.</p><div class="grid three">')
audio=[]
for name in ['press','go','jump','launch','hit','crash','rank','victory']:
 f=R.parents[1]/'assets/snap-audio'/(name+'.wav')
 with wave.open(str(f)) as a:dur=a.getnframes()/a.getframerate()
 audio.append(dict(cue=name,seconds=dur));sections.append(f'<div><p>{name} / {round(dur*1000)} ms</p><audio controls preload="none" src="../../assets/snap-audio/{name}.wav"></audio></div>')
sections.append('</div></section>');(R/'motion-storyboards/audio-review.json').write_text(json.dumps(audio,indent=2))
sections.append('<section id="decision"><p class="eyebrow">07 / REVIEW GATE</p><h2>Choose the world.<br>Then build one slice.</h2><p>Approve A, B or C—or specify what needs revision. No visual approval has been assumed. The next implementation phase would first prove one component/Home/HUD slice, fix the carried client-Final regression, and perform actual-engine comparisons before extending the rest.</p><p><a href="implementation-feasibility.md">Roblox feasibility, input, safe areas, accessibility and performance risks</a> · <a href="design-principles.md">Design principles</a> · <a href="README.md">Package inventory, reproduction and limitations</a></p><p class="notice">Design branch only. No game publishing, merging, sound upload, server/economy change or replacement UI implementation.</p></section>')
css='''@font-face{font-family:Fredoka;src:url(source/fonts/FredokaOne-Regular.ttf)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff9e9;color:#20334c;font:17px/1.6 Arial,sans-serif}header,section{padding:64px max(24px,calc((100vw - 1400px)/2));border-bottom:1px solid #ccd6ca}header{background:#c8e9d9}h1,h2,h3,button{font-family:Fredoka,Arial;line-height:1.15}h1{font-size:clamp(52px,6.4vw,96px);margin:30px 0}h2{font-size:clamp(32px,4vw,55px);margin:18px 0 24px}h3{font-size:25px;margin-top:36px}em{font-style:normal;color:#c64736}.eyebrow{font-size:12px;font-weight:bold;letter-spacing:1.8px}.lead{font-size:24px}.notice{max-width:1100px;padding:18px 22px;border-left:5px solid #f66b55;background:#ffffff80}a{color:#294e9a;text-underline-offset:4px}nav{display:flex;flex-wrap:wrap;gap:24px;margin-top:36px}nav a{color:#20334c;font-weight:bold}figure{margin:20px 0}img{max-width:100%;height:auto;display:block;border-radius:8px}figcaption{font-size:13px;line-height:1.5;margin-top:9px}figcaption b{display:block}small{font-size:12px}.grid{display:grid;gap:28px}.two{grid-template-columns:repeat(2,minmax(0,1fr))}.three{grid-template-columns:repeat(3,minmax(0,1fr))}.portrait img{max-height:650px;width:auto;margin:auto}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:30px 0}button{background:#fff9e9;color:#20334c;border:2px solid #20334c;border-radius:12px;padding:12px 18px;cursor:pointer}button:hover{background:#c8e9d9}button:focus-visible,a:focus-visible{outline:3px solid #5579d9;outline-offset:4px}iframe{display:block;width:100%;height:630px;border:2px solid #20334c;border-radius:16px}audio{max-width:100%}[hidden]{display:none!important}@media(max-width:850px){.three{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.three,.two{grid-template-columns:1fr}header,section{padding:40px 20px}iframe{height:740px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
js='''document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('#screens [data-device]').forEach(el=>{el.hidden=b.dataset.filter!=='all'&&el.dataset.device!==b.dataset.filter})});'''
(R/'review-gallery.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TRAIL WARS — cartoon art direction approval</title><style>'+css+'</style>'+''.join(sections)+'<script>'+js+'</script></html>',encoding='utf-8')
print('Built local approval gallery; no service or game connection')
